use alloy_primitives::{B256, keccak256};
use secp256k1::{Message, PublicKey, SecretKey, ecdsa::{RecoverableSignature, RecoveryId}};
use serde_json::{Value, json};
use std::{env, fs, hint::black_box, io::{self, BufRead}, time::{Duration, Instant}};

struct EcInput {
    message: B256,
    signature: [u8; 64],
    id: u8,
    parsed: RecoverableSignature,
    public: PublicKey,
    encoded: [u8; 65],
    address: B256,
}

fn decode<const N: usize>(value: &str) -> [u8; N] {
    let value = value.strip_prefix("0x").unwrap_or(value);
    assert_eq!(value.len(), N * 2);
    std::array::from_fn(|i| u8::from_str_radix(&value[2 * i..2 * i + 2], 16).unwrap())
}

fn ec_input(message: [u8; 32], signature: [u8; 65]) -> EcInput {
    let id = signature[64];
    let signature: [u8; 64] = signature[..64].try_into().unwrap();
    let parsed = RecoverableSignature::from_compact(&signature, RecoveryId::try_from(i32::from(id)).unwrap()).unwrap();
    let public = parsed.recover_ecdsa(Message::from_digest(message)).unwrap();
    let encoded = public.serialize_uncompressed();
    let mut address = keccak256(&encoded[1..]);
    address[..12].fill(0);
    assert_eq!(evm2::precompiles::crypto().secp256k1_ecrecover(&signature, id, &message).unwrap(), address.0);
    assert_eq!(pure_rust_backend::ecrecover((&signature).into(), id, (&message).into()).unwrap(), address);
    EcInput {message: message.into(), signature, id, parsed, public, encoded, address}
}

struct Case<'a> {
    name: &'static str,
    operation: Box<dyn FnMut(usize) + 'a>,
    iterations: usize,
    samples: Vec<f64>,
}

fn add<'a>(cases: &mut Vec<Case<'a>>, name: &'static str, operation: impl FnMut(usize) + 'a) {
    cases.push(Case {name, operation: Box::new(operation), iterations: 1, samples: Vec::new()});
}

fn batch(case: &mut Case<'_>, offset: usize) -> f64 {
    let started = Instant::now();
    for i in 0..case.iterations { (case.operation)(i.wrapping_add(offset)); }
    started.elapsed().as_nanos() as f64 / case.iterations as f64
}

fn main() {
    let args: Vec<_> = env::args().collect();
    let mut line = String::new();
    io::stdin().lock().read_line(&mut line).unwrap();
    assert_eq!(line.trim(), "start");
    let corpus: Value = serde_json::from_slice(&fs::read(&args[1]).unwrap()).unwrap();
    let original = ec_input(decode(corpus["ecdsa"]["message"].as_str().unwrap()), decode(corpus["ecdsa"]["signature"].as_str().unwrap()));
    assert_eq!(original.address.0, decode::<32>(corpus["ecdsa"]["address_word"].as_str().unwrap()));
    let geth = ec_input(decode("ce0677bb30baa8cf067c88db9811f4333d131bf8bcf12fe7065d211dce971008"),
                        decode("90f27b8b488db00b00606796d2987f6a5f59ae62ea05effe84fef5b8b0e549984a691139ad57a3f0b906637673aa2f63d1f55cb1a69199d4009eea23ceaddc9301"));
    let mut ec_corpus = Vec::new();
    for index in 0..32 {
        let secret_bytes = keccak256(format!("recovery audit key {index}"));
        let secret = SecretKey::from_secret_bytes(secret_bytes.0).unwrap();
        let message = keccak256(format!("recovery audit message {index}"));
        let signed = RecoverableSignature::sign_ecdsa_recoverable(Message::from_digest(message.0), &secret);
        let (id, compact) = signed.serialize_compact();
        let mut signature = [0; 65];
        signature[..64].copy_from_slice(&compact);
        signature[64] = id.to_u8();
        ec_corpus.push(ec_input(message.0, signature));
    }
    let pq: Vec<_> = corpus["cases"].as_array().unwrap().iter().map(|value| {
        let key = B256::from(decode::<32>(value["public_key"].as_str().unwrap()));
        let message = B256::from(decode::<32>(value["message"].as_str().unwrap()));
        let signature = decode::<7740>(value["signature"].as_str().unwrap());
        assert!(lean_sphincs::verify(&key, &message, &signature));
        (key, message, signature)
    }).collect();
    let provider = evm2::precompiles::crypto();
    let mut cases = Vec::new();
    for (name, fixture) in [("evm2/original_fixture", &original), ("evm2/geth_fixture", &geth)] {
        add(&mut cases, name, move |_| {
            black_box(provider.secp256k1_ecrecover(black_box(&fixture.signature), black_box(fixture.id), black_box(&fixture.message.0))).unwrap();
        });
    }
    add(&mut cases, "evm2/32_fixtures", |i| {
        let input = &ec_corpus[i % ec_corpus.len()];
        black_box(provider.secp256k1_ecrecover(black_box(&input.signature), black_box(input.id), black_box(&input.message.0))).unwrap();
    });
    add(&mut cases, "libsecp256k1/recover_only", |i| {
        let input = &ec_corpus[i % ec_corpus.len()];
        black_box(black_box(&input.parsed).recover_ecdsa(Message::from_digest(black_box(input.message.0)))).unwrap();
    });
    add(&mut cases, "libsecp256k1/recover_and_serialize", |i| {
        let input = &ec_corpus[i % ec_corpus.len()];
        let public = black_box(&input.parsed).recover_ecdsa(Message::from_digest(black_box(input.message.0))).unwrap();
        black_box(public.serialize_uncompressed());
    });
    add(&mut cases, "libsecp256k1/parse_only", |i| {
        let input = &ec_corpus[i % ec_corpus.len()];
        black_box(RecoverableSignature::from_compact(black_box(&input.signature), RecoveryId::try_from(i32::from(black_box(input.id))).unwrap())).unwrap();
    });
    add(&mut cases, "libsecp256k1/serialize_only", |i| {
        black_box(black_box(&ec_corpus[i % ec_corpus.len()].public).serialize_uncompressed());
    });
    add(&mut cases, "address_hash_only", |i| {
        let mut hash = keccak256(black_box(&ec_corpus[i % ec_corpus.len()].encoded[1..]));
        hash[..12].fill(0);
        black_box(hash);
    });
    add(&mut cases, "evm2_k256_backend/32_fixtures", |i| {
        let input = &ec_corpus[i % ec_corpus.len()];
        black_box(pure_rust_backend::ecrecover(black_box((&input.signature).into()), black_box(input.id), black_box(&input.message))).unwrap();
    });
    add(&mut cases, "lean_sphincs/11_fixtures", |i| {
        let (key, message, signature) = &pq[i % pq.len()];
        black_box(lean_sphincs::verify(black_box(key), black_box(message), black_box(signature)));
    });
    for case in &mut cases {
        let warmup = Instant::now();
        while warmup.elapsed() < Duration::from_millis(250) { (case.operation)(0); }
        while batch(case, 0) * (case.iterations as f64) < 20_000_000.0 { case.iterations *= 2; }
    }
    let mut seed = args[3].parse::<u64>().unwrap();
    let mut order: Vec<_> = (0..cases.len()).collect();
    for sample in 0..44 {
        for position in (1..order.len()).rev() {
            seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17;
            order.swap(position, seed as usize % (position + 1));
        }
        for &index in &order {
            let elapsed = batch(&mut cases[index], sample);
            cases[index].samples.push(elapsed);
        }
    }
    let measurements: Vec<_> = cases.iter().map(|case| {
        let mut sorted = case.samples.clone();
        sorted.sort_by(f64::total_cmp);
        json!({"name": case.name, "iterations": case.iterations, "samples_ns": case.samples, "median_ns": (sorted[21] + sorted[22]) / 2.0})
    }).collect();
    let report = json!({"sample_rounds":44,"batch_target_ms":20,"ecdsa_inputs":32,"pq_inputs":11,"measurements":measurements});
    fs::write(&args[2], serde_json::to_vec_pretty(&report).unwrap()).unwrap();
    for case in &measurements { println!("{} {:.3} us",case["name"].as_str().unwrap(),case["median_ns"].as_f64().unwrap()/1000.0); }
}
